import { appendFileSync, existsSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { GLINT_HOME, ensureDirs } from "./config.ts";

const MEMORY_PATH = join(GLINT_HOME, "memory.md");

export function readMemory(): string {
  try {
    return readFileSync(MEMORY_PATH, "utf8").trim();
  } catch {
    return "";
  }
}

export function appendMemory(fact: string): void {
  ensureDirs();
  const stamp = new Date().toISOString().slice(0, 10);
  appendFileSync(MEMORY_PATH, `- ${fact} _(${stamp})_\n`, { mode: 0o600 });
}

export function memoryPath(): string {
  return MEMORY_PATH;
}
